import json

with open('/app/output/charts.json') as f:
    charts = json.load(f)
with open('/app/output/stats.json') as f:
    s = json.load(f)

# Helper formatting
def fmt(v, dec=0):
    if v is None:
        return 'N/A'
    return f"{v:,.{dec}f}"

def pct(v, dec=1):
    if v is None:
        return 'N/A'
    return f"{v:.{dec}f}%"

# Build geo arbitrage tables HTML
geo_df_records = s['geo_df']

def geo_table(brand):
    rows = [r for r in geo_df_records if r['brand']==brand]
    rows.sort(key=lambda x: x['pct_diff'], reverse=True)
    html = '<table><thead><tr><th>Country</th><th>Listings</th><th>Median Price</th><th>vs Global Median</th></tr></thead><tbody>'
    for r in rows:
        color = '#27AE60' if r['pct_diff'] >= 0 else '#C0392B'
        sign = '+' if r['pct_diff'] >= 0 else ''
        html += f'<tr><td>{r["country"]}</td><td>{r["n"]}</td><td>${fmt(r["median"],2)}</td><td style="color:{color};font-weight:600">{sign}{pct(r["pct_diff"],1)}</td></tr>'
    html += '</tbody></table>'
    return html

